package main

import (
    "bufio"
    "fmt"
    "os"
)

func main() {
    in := bufio.NewReader(os.Stdin)
    var s string
    if _, err := fmt.Fscan(in, &s); err != nil { return }
    var n int
    fmt.Fscan(in, &n)
    dict := make(map[string]bool)
    for i := 0; i < n; i++ {
        var w string
        fmt.Fscan(in, &w)
        dict[w] = true
    }
    dp := make([]bool, len(s)+1)
    dp[0] = true
    for i := 1; i <= len(s); i++ {
        for j := 0; j < i; j++ {
            if dp[j] && dict[s[j:i]] {
                dp[i] = true
                break
            }
        }
    }
    if dp[len(s)] { fmt.Println("true") } else { fmt.Println("false") }
}

